-- V600b DAILY PLANT CHECKLISTS: the five paper PM sheets rebuilt as DAILY checklists
-- STATUS: authored 2026-10-26. Additive only: inserts 6 NEW checklist_templates rows (published),
-- touches no existing template, no table, no policy.
--
-- OWNER RULE: these are DAILY checklists, one submission per asset per day, built
-- exactly like Workshop Daily / Fleet Transit Mixer (8-mark legend, Not OK blocks
-- sign-off and needs a note, ar/hi/ur on every label, asset-filled location, signature).
-- The paper monthly grid is NOT a data-entry pattern: the existing monthly grid
-- (MonthlyGridPanel) rolls these daily submissions up for REPORTING only.
-- Monthly paper tasks sit behind a "Monthly tasks due today?" choice, so the daily
-- sheet stays short on all days except the first week.
--
-- Sources: F-KSA-PPM-005 (Ice Plant), F-KSA-PPM-007 (Chiller), Air Compressor sheet,
-- Batching Plant daily sheet, Genset PM report, F-KSA-PPM-008 (Chiller log).
-- Genset adds a 9th mark "Cleaned" (paper work code 3-Clean) on its own legend only.
-- Spare-part cost and technician rate/amount of the Genset paper report are NOT
-- priced here (no price source on a checklist); parts are recorded as text.
-- ROLLBACK: delete from public.checklist_templates where doc_prefix in ('ICP','CHL','ACP','BPD','GSR','CLG') and version = 1 and (select count(*) from public.checklist_submissions s where s.template_id = checklist_templates.id) = 0;

insert into public.checklist_templates
  (organisation_id,name,name_i18n,description,category,icon,status,version,require_signature,require_approval,require_area_manager,doc_prefix,assignee_roles,fields,option_sets)
