  $s${"legend":{"options":["OK","Not OK","Not applicable","Changed","Repaired","Added / Top-Up","Adjusted","Lubricated"],"i18n":{"ar":["سليم","غير سليم","لا ينطبق","تم التغيير","تم الإصلاح","تمت الإضافة","تم الضبط","تم التشحيم"],"hi":["ठीक","ठीक नहीं","लागू नहीं","बदला गया","मरम्मत की गई","भरा गया","समायोजित","ग्रीस लगाया"],"ur":["ٹھیک","ٹھیک نہیں","لاگو نہیں","تبدیل کیا","مرمت کی","شامل کیا","ایڈجسٹ کیا","گریس کیا"]},"meta":[{"value":"OK","icon":"ok","tone":"good","meaning":"Checked and correct. Nothing needed."},{"value":"Not OK","icon":"fault","tone":"bad","meaning":"A fault is present and has NOT been put right. Say what is wrong."},{"value":"Not applicable","icon":"na","tone":"muted","meaning":"This machine does not have this item."},{"value":"Changed","icon":"swap","tone":"fixed","meaning":"The part was replaced."},{"value":"Repaired","icon":"repair","tone":"fixed","meaning":"The fault was found and repaired."},{"value":"Added / Top-Up","icon":"topup","tone":"fixed","meaning":"Fluid or consumable was topped up."},{"value":"Adjusted","icon":"adjust","tone":"fixed","meaning":"Set back within limits without replacing anything."},{"value":"Lubricated","icon":"lubricant","tone":"fixed","meaning":"Greased or oiled as part of the check."}],"blocking":["Not OK"],"require_note":["Not OK"]}}$s$::jsonb
